<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { canGovernance as can } from '../../governance/permissions.js'
import { dutyAll } from '../../duty/api.js'
import { createClientId } from '../../clientId.js'
import { governanceRead, governanceWrite, governanceExport, governanceUpload, governanceAttachment, governanceMedia } from '../../governance/api.js'
import { conflictMessage, eventLabel, label, recordBody, reportDifferences, sameSignal, time, tone } from '../../governance/helpers.js'
import VerificationDialog from './VerificationDialog.vue'
import GovernanceResults from './GovernanceResults.vue'
const props=defineProps({caseId:String,devices:Array,configs:Object,runs:Array,snapshot:Object,adoption:Object})
const emit=defineEmits(['refresh','navigate','analyse','viewRun'])
const record=ref(null),rounds=ref([]),roundId=ref(''),reports=ref([]),data=reactive({}), loading=ref(false),saving=ref(false),error=ref(''),tab=ref('facts'),dialog=ref(''),form=reactive({}), verificationDialog=ref(false),verificationInitial=ref(null)
const current=computed(()=>recordBody(record.value)),round=computed(()=>rounds.value.map(recordBody).find(row=>row.id===roundId.value)),editable=computed(()=>round.value?.status==='ACTIVE'&&roundId.value===current.value?.currentRoundId)
const names=['alarm-links','verification-links','causes','measures','observation-plans','observation-reviews']
const observationRange=ref([Date.now()-7*86400000,Date.now()+1]),observationCursor=ref('')
const verificationRows=ref([]), observations=ref([]),attachments=ref([]),file=ref(null),attachmentKey=ref(''),selected=ref(null)
const totals=reactive({}),moreBusy=ref(''),reportAnalysis=ref(null),reportLoading=ref(false),reportError=ref(''),selectedReport=ref(null),verificationOffset=ref(0)
const deviceName=id=>props.devices.find(row=>row.id===id)?.name||id
let generation=0
async function load(){const token=++generation;loading.value=true;error.value='';try{const [caseValue,roundValue,reportValue]=await Promise.all([governanceRead('cases',props.caseId),governanceRead('cases',props.caseId,'rounds',{limit:100}),governanceRead('cases',props.caseId,'reports',{limit:100})]);if(token!==generation)return;record.value=caseValue;rounds.value=roundValue.items||[];totals.rounds=roundValue.total??rounds.value.length;reports.value=(reportValue.items||[]).map(recordBody);totals.reports=reportValue.total??reports.value.length;if(!rounds.value.some(row=>row.id===roundId.value))roundId.value=current.value.currentRoundId;await loadRound(token);await loadEvents();const links=await governanceRead('cases',props.caseId,'business-links',{limit:100});if(token===generation){businessLinks.value=(links.items||[]).map(recordBody);totals['business-links']=links.total??businessLinks.value.length}}catch(cause){if(token===generation)error.value=conflictMessage(cause)}finally{if(token===generation)loading.value=false}}
async function loadRound(parentToken=generation){if(!roundId.value)return;const id=roundId.value;const results=await Promise.allSettled(names.map(name=>governanceRead('rounds',id,name,{limit:100})));if(parentToken!==generation||id!==roundId.value)return;results.forEach((result,index)=>{data[names[index]]=result.status==='fulfilled'?(result.value.items||[]).map(recordBody):[];totals[names[index]]=result.status==='fulfilled'?(result.value.total??data[names[index]].length):0});const failed=results.find(row=>row.status==='rejected');if(failed)error.value=failed.reason.message;const extras=await Promise.allSettled([governanceRead('verifications','','',{deviceIds:[current.value.deviceId],limit:100}),governanceRead('observations','','',{deviceIds:[current.value.deviceId],componentId:current.value.componentId,alarmType:current.value.alarmType,originKind:current.value.originKind,signalKey:current.value.signalKey,start:observationRange.value?.[0],end:observationRange.value?.[1],limit:100}),governanceRead('cases',props.caseId,'attachments',{limit:100})]);if(parentToken!==generation||id!==roundId.value)return;verificationRows.value=extras[0].status==='fulfilled'?(extras[0].value.items||[]).map(recordBody).filter(row=>sameSignal(row,current.value)):[];observations.value=extras[1].status==='fulfilled'?(extras[1].value.items||[]).map(recordBody).filter(row=>['deviceId','componentId','alarmType','originKind','signalKey'].every(key=>(row[key]||'')===(current.value[key]||''))):[];if(extras[1].status==='fulfilled')observationCursor.value=extras[1].value.nextCursor||'';else error.value=extras[1].reason.message;attachments.value=extras[2].status==='fulfilled'?(extras[2].value.items||[]).map(recordBody):[];totals.verifications=extras[0].status==='fulfilled'?(extras[0].value.total??verificationRows.value.length):0;verificationOffset.value=extras[0].status==='fulfilled'?(extras[0].value.items?.length||0):0;totals.attachments=extras[2].status==='fulfilled'?(extras[2].value.total??attachments.value.length):0}
async function more(kind){if(moreBusy.value)return;const token=generation,id=roundId.value;moreBusy.value=kind;try{let collection='rounds',parent=id,query={limit:100},target;if(['rounds','reports','business-links','attachments'].includes(kind)){collection='cases';parent=props.caseId;target={rounds,reports,'business-links':businessLinks,attachments}[kind];query.offset=target.value.length}else if(kind==='verifications'){collection='verifications';parent='';target=verificationRows;query={...query,deviceIds:[current.value.deviceId],offset:verificationOffset.value}}else query.offset=(data[kind]||[]).length;const page=await governanceRead(collection,parent,parent?kind:'',query);if(token!==generation||id!==roundId.value)return;const rows=(page.items||[]).map(recordBody);if(target){if(kind==='verifications'){verificationOffset.value+=rows.length;target.value.push(...rows.filter(row=>sameSignal(row,current.value)))}else target.value.push(...rows)}else data[kind].push(...rows);totals[kind]=page.total??(target?target.value.length:data[kind].length)}catch(cause){error.value=cause.message}finally{moreBusy.value=''}}
async function showReport(row){selectedReport.value=row;reportAnalysis.value=null;reportError.value='';reportLoading.value=true;const token=generation;try{const value=await governanceRead('reports',row.id,'analysis');if(token!==generation||selectedReport.value?.id!==row.id)return;if(value.snapshot?.id!==row.analysisSnapshotId||value.snapshot?.factsHash!==row.factsHash)throw new Error('报告固定快照身份不一致，请重新读取');reportAnalysis.value=value}catch(cause){reportError.value=cause.message}finally{reportLoading.value=false}}
const reportPlans=computed(()=>selectedReport.value?.resources?.filter(row=>row.kind==='observation-plan').map(recordBody)||[])
async function moreObservations(){try{const value=await governanceRead('observations','','',{deviceIds:[current.value.deviceId],componentId:current.value.componentId,alarmType:current.value.alarmType,originKind:current.value.originKind,signalKey:current.value.signalKey,start:observationRange.value?.[0],end:observationRange.value?.[1],limit:100,cursor:observationCursor.value});observations.value=[...observations.value,...(value.items||[]).map(recordBody)];observationCursor.value=value.nextCursor||''}catch(cause){error.value=cause.message}}
function open(kind,row=null){selected.value=row;dialog.value=kind;error.value='';Object.keys(form).forEach(key=>delete form[key]);Object.assign(form,{reason:'',ownerUserId:current.value.ownerUserId,observationIds:[],verificationIds:[],supportEvidenceIds:[],conflictEvidenceIds:[],cause:'',confirmationBasis:'',content:'',dueAt:null,required:true,requiresAcceptance:false,basis:'',implementation:'',acceptance:'',cancellationReason:'',followup:'',before:null,after:null,minimumMonitoringHours:null,minimumActivities:null,coverageRequirement:'FULL_DECLARED',activityUnit:'',activityType:'',timeBasis:'EVENT_AT',monitoringIntervals:[],beforeConditions:'',afterConditions:'',reviewerUserId:current.value.ownerUserId,admissionText:'',exclusionsText:'',planId:'',runId:'',conclusion:'',limitationsText:'',followupOwnerUserId:current.value.ownerUserId,verificationId:'',targetKind:'',targetId:'',targetVersion:0,relation:'',templateRevisionId:current.value.templateRevisionId,scenePresetRevisionId:current.value.scenePresetRevisionId,typeProfileRevisionId:current.value.typeProfileRevisionId,assetInstanceId:'',identityBasis:'',idempotencyKey:createClientId()});if(row){form.confirmationBasis=row.confirmationBasis||'';form.supportEvidenceIds=row.supportEvidenceIds?.slice()||[];form.conflictEvidenceIds=row.conflictEvidenceIds?.slice()||[]}}
async function mutate(){if(saving.value)return;saving.value=true;error.value='';try{let value={...form,idempotencyKey:form.idempotencyKey};let collection='cases',id=props.caseId,operation=dialog.value,method='POST';
 if(['causes','measures','observation-plans','observation-reviews','alarm-links','verification-links'].includes(dialog.value)){collection='rounds';id=roundId.value;
 if(dialog.value==='observation-plans'){if(!form.before||!form.after)throw new Error('请填写前后观察窗口');value={...value,beforeStart:form.before[0],beforeEnd:form.before[1],afterStart:form.after[0],afterEnd:form.after[1],admissionConditions:form.admissionText.split('\n').filter(Boolean),exclusions:form.exclusionsText.split('\n').filter(Boolean),monitoringIntervals:form.monitoringIntervals.map(row=>({deviceId:current.value.deviceId,start:row.range?.[0],end:row.range?.[1],kind:row.kind,basis:row.basis})),measureVersions:Object.fromEntries((data.measures||[]).map(row=>[row.id,row.version]))}}
 if(dialog.value==='observation-reviews'){const plan=(data['observation-plans']||[]).find(row=>row.id===form.planId);const run=(props.runs||[]).find(row=>row.id===form.runId);if(!plan||!run?.snapshotId)throw new Error('请选择已确认计划与已完成固定分析');const snapshot=await governanceRead('runs',run.id,'snapshot');value={...value,roundId:roundId.value,planVersion:plan.version,analysisSnapshotId:run.snapshotId,factsHash:snapshot.factsHash||'',sourceRevisionVector:snapshot.statistics?.sourceRevisionVector||[],dataRevision:snapshot.statistics?.dataRevision??current.value.dataRevision,limitations:form.limitationsText.split('\n').filter(Boolean)} }
 if(dialog.value==='verification-links'){const verification=verificationRows.value.find(row=>row.id===form.verificationId);value.verificationVersion=verification?.version}
 }else if(dialog.value==='business-links'){operation='business-links';value={targetKind:form.targetKind,targetId:form.targetId,targetVersion:form.targetVersion,relation:form.relation+(form.reason?'；依据：'+form.reason:''),idempotencyKey:form.idempotencyKey}}else if(selected.value){collection=dialog.value.split(':')[0];id=selected.value.id;operation=dialog.value.split(':')[1];value.expectedVersion=selected.value.version;if(dialog.value==='attachments:withdraw'){operation='';method='DELETE';value={expectedVersion:selected.value.version,reason:form.reason}}if(dialog.value==='causes:confirm'&&form.confirmationBasis!==selected.value.confirmationBasis){if(!can('PATCH /api/v1/alarm-governance/causes/:id'))throw new Error('没有修改候选依据权限');const updated=await governanceWrite('causes',id,'',{...selected.value,confirmationBasis:form.confirmationBasis,expectedVersion:selected.value.version,idempotencyKey:form.idempotencyKey+':basis'},'PATCH');value.expectedVersion=updated.version}}else{value.expectedVersion=current.value.version;value.dataRevision=current.value.dataRevision;if(dialog.value==='complete'){const review=(data['observation-reviews']||[]).find(row=>row.id===form.reviewId);if(!review)throw new Error('请选择已确认观察评价');value={...value,reviewId:review.id,analysisSnapshotId:review.analysisSnapshotId,factsHash:review.factsHash,dataRevision:review.dataRevision}} }
 const permission=collection==='rounds'?`${method} /api/v1/alarm-governance/rounds/:id/${operation}`:`${method} /api/v1/alarm-governance/${collection}/:id${operation?'/'+operation:''}`;if(!can(permission))throw new Error('当前账户没有此动作权限');await governanceWrite(collection,id,operation,value,method);dialog.value='';await load();emit('refresh')}catch(cause){error.value=conflictMessage(cause)}finally{saving.value=false}}
async function upload(){if(!file.value||saving.value)return;saving.value=true;try{await governanceUpload('cases',props.caseId,file.value,[current.value.deviceId],attachmentKey.value||createClientId());file.value=null;await load()}catch(cause){error.value=cause.message}finally{saving.value=false}}
const businessLinks=ref([]),sourceChoices=ref([]),sourceCursor=ref(''),sourceRange=ref([Date.now()-7*86400000,Date.now()+1]),sourceLoading=ref(false),reviewSnapshot=ref(null),eventPage=ref(1),eventTotal=ref(0)
async function loadEvents(){const id=roundId.value;try{const value=await governanceRead('rounds',id,'events',{limit:20,offset:(eventPage.value-1)*20});if(id!==roundId.value)return;data.events=(value.items||[]).map(recordBody);eventTotal.value=value.total||0}catch(cause){error.value=cause.message}}
watch(eventPage,loadEvents)
async function loadVideoSources(append=false){if(!sourceRange.value||!can('GET /api/v1/alarm-governance/video-events'))return;sourceLoading.value=true;try{const value=await governanceRead('video-events','','',{deviceIds:[current.value.deviceId],start:sourceRange.value[0],end:sourceRange.value[1],cursor:append?sourceCursor.value:'',limit:100});const rows=(value.items||[]).map(row=>({...row,id:row.eventId,version:row.targetVersion,title:`${row.cameraName||'摄像头'} · ${row.alarmName||row.alarmType||'历史事件'} · ${time(row.eventTime)}`}));sourceChoices.value=append?[...sourceChoices.value,...rows]:rows;sourceCursor.value=value.nextCursor||''}catch(cause){error.value=cause.message}finally{sourceLoading.value=false}}
watch(()=>form.targetKind,async kind=>{sourceChoices.value=[];sourceCursor.value='';form.targetId='';form.targetVersion=0;if(dialog.value!=='business-links'||!kind)return;if(kind==='VIDEO_EVENT'){await loadVideoSources();return}sourceLoading.value=true;try{const value=await dutyAll(kind==='DUTY_ITEM'?'items':'records');sourceChoices.value=(value.items||[]).map(recordBody).filter(row=>row.deviceId===current.value.deviceId)}catch(cause){error.value=cause.message}finally{sourceLoading.value=false}})
watch(()=>form.targetId,id=>{const row=sourceChoices.value.find(row=>row.id===id);if(row)form.targetVersion=row.version})
watch(()=>form.runId,async id=>{reviewSnapshot.value=null;if(dialog.value!=='observation-reviews'||!id)return;try{const value=await governanceRead('runs',id,'snapshot');if(form.runId!==id||dialog.value!=='observation-reviews')return;reviewSnapshot.value=value;form.conclusion=value.statistics?.comparison?.conclusion||'';form.limitationsText=(value.statistics?.comparison?.limitations||[]).join('\n')}catch(cause){error.value=cause.message}})
const comparisonPrevious=ref(''),comparisonCurrent=ref('')
const reportChanges=computed(()=>reportDifferences(reports.value.find(row=>row.id===comparisonPrevious.value),reports.value.find(row=>row.id===comparisonCurrent.value)))
const caseActions=computed(()=>current.value?.status==='COMPLETED'?['reopen']:!editable.value?[]:['assign',...(current.value.identityQuality==='UNKNOWN'?['confirm-identity']:[]),...(current.value.status==='PENDING_INVESTIGATION'?['start']:[]),...(['INVESTIGATING','IMPROVING'].includes(current.value.status)?['start-observation']:[]),...(current.value.status==='OBSERVING'?['complete']:[]),'cancel'])
const measureActions=row=>row.status==='PLANNED'?['start','implement','cancel']:row.status==='IN_PROGRESS'?['implement','cancel']:row.status==='IMPLEMENTED'?['verify','cancel']:[]
const list=key=>data[key]||[]
let adopted=null
watch(()=>[props.adoption,editable.value],([item,canEdit])=>{if(item&&canEdit&&item!==adopted){adopted=item;open('causes');form.cause=item.text||item.explanation||'';form.supportEvidenceIds=item.factIds?.slice()||[];form.confirmationBasis='AI候选解释，仍需实际事件、核实与冲突依据';} });
onBeforeUnmount(()=>{generation++})
watch(()=>props.caseId,()=>{adopted=null;roundId.value='';void load()},{immediate:true});watch(roundId,()=>{eventPage.value=1;void loadEvents();return loadRound().catch(cause=>error.value=cause.message)})
</script>
<template><section class="gov-stack"><ui-alert v-if="error&&!dialog" :title="error" type="error" :closable="false"><ui-button size="small" @click="load">刷新最新资料</ui-button></ui-alert><ui-skeleton v-if="loading&&!current" :rows="5"/><template v-if="current"><div class="gov-toolbar"><div><h2>{{current.title}}</h2><p class="gov-meta">{{deviceName(current.deviceId)}} · {{current.componentId||'设备点位'}} · {{current.alarmType}} · {{label(current.originKind)}} · {{current.signalKey}}</p><p class="gov-meta">{{current.location||'位置未确认'}} · 负责人 {{current.ownerUserId}} · 资料版本 {{current.dataRevision}} · 实物身份 {{label(current.identityQuality)}}</p></div><ui-tag :type="tone(current.status)">{{label(current.status)}}</ui-tag></div><div class="gov-actions"><ui-button size="small" @click="load">刷新</ui-button><ui-button v-if="can('POST /api/v1/alarm-governance/verifications')" size="small" @click="verificationInitial=current;verificationDialog=true">填写核实</ui-button><ui-button v-if="editable&&can('POST /api/v1/alarm-governance/runs')" size="small" @click="emit('analyse',{...current,roundId})">固定事实分析</ui-button><ui-button v-for="action in caseActions" v-show="can(`POST /api/v1/alarm-governance/cases/:id/${action}`)&&((action==='reopen'&&current.status==='COMPLETED')||(editable&&action!=='reopen'))" :key="action" size="small" @click="open(action)">{{{start:'开始核查',assign:'重新指派','confirm-identity':'确认实物身份','start-observation':'开始观察',complete:'确认完成本轮',cancel:'取消本轮',reopen:'复核复发并重开'}[action]}}</ui-button></div><ui-alert v-if="current.status==='COMPLETED'" type="warning" :closable="false" title="本轮完成表示已完成人工评价；请同时查看评价结果和后续责任。新增事件须重新核实。"/><ui-select v-model="roundId" class="gov-compact"><ui-option v-for="row in rounds.map(recordBody)" :key="row.id" :value="row.id" :label="`第 ${row.number} 轮 · ${label(row.status)} · ${time(row.startedAt)}`"/></ui-select><p class="gov-meta">固定模板 {{round?.templateRevisionId}} · 场景 {{round?.scenePresetRevisionId}} · 类型 {{round?.typeProfileRevisionId}}；历史轮次按原版本呈现。</p><ui-tabs v-model="tab"><ui-tab-pane name="facts" label="事件与核实"/><ui-tab-pane name="causes" label="原因与措施"/><ui-tab-pane name="observation" label="观察与正式报告"/><ui-tab-pane name="history" label="附件与时间线"/></ui-tabs>
<div v-if="tab==='facts'" class="gov-stack"><div class="gov-toolbar"><ui-date-range v-model="observationRange"/><ui-button size="small" @click="loadRound().catch(cause=>error=cause.message)">读取本区间事件</ui-button></div><div class="gov-actions"><ui-button v-if="editable&&can('POST /api/v1/alarm-governance/rounds/:id/alarm-links')" size="small" @click="open('alarm-links')">追加具体事件关联</ui-button><ui-button v-if="editable&&can('POST /api/v1/alarm-governance/rounds/:id/verification-links')" size="small" @click="open('verification-links')">关联独立核实</ui-button></div><article v-for="row in observations" :key="row.id" class="gov-card"><strong>{{label(row.factKind)}} · {{time(row.eventAt)}}</strong><p class="gov-meta">源时间 {{label(row.timeQuality)}} · 接收 {{time(row.receivedAt)}} · 持久化可用 {{time(row.availableAt)}} · {{label(row.acceptance)}} · {{row.id}}</p><ui-button v-if="row.rawMessageId&&can('menu:raw')" text size="small" @click="emit('navigate','raw',{deviceId:row.deviceId,rawMessageId:row.rawMessageId})">查看原文</ui-button></article><ui-empty v-if="!observations.length" description="尚无可读取逐次事件。历史不足保持未知。"/><ui-button v-if="observationCursor" size="small" @click="moreObservations">加载更多具体事件</ui-button><h3>现场核实记录</h3><article v-for="row in verificationRows" :key="row.id" class="gov-card"><div class="gov-toolbar"><strong>{{label(row.fieldResult)}}</strong><ui-tag>{{label(row.status)}}</ui-tag></div><p>{{row.description}}</p><p class="gov-meta">{{label(row.verificationMethod)}} · 实际核实 {{time(row.verifiedAt)}} · 登记 {{time(row.recordedAt)}} · {{label(row.activityRelation)}} · 事件 {{row.observationIds?.length||0}} 条</p><p class="gov-meta">检查范围 {{row.checkScope||'未补充'}} · 原记录版本 {{row.version}} · {{list('verification-links').some(link=>link.verificationId===row.id)?'已关联本轮':'独立记录，未自动关联本轮'}}</p><ui-button v-if="can(row.status==='DRAFT'?'PATCH /api/v1/alarm-governance/verifications/:id':'POST /api/v1/alarm-governance/verifications/:id/corrections')" text size="small" @click="verificationInitial=row;verificationDialog=true">{{row.status==='DRAFT'?'编辑草稿':'追加更正'}}</ui-button><ui-button v-if="row.status==='DRAFT'&&can('POST /api/v1/alarm-governance/verifications/:id/confirm')" text size="small" @click="open('verifications:confirm',row)">确认本次核实</ui-button></article></div>
<div v-if="tab==='causes'" class="gov-stack"><div class="gov-actions"><ui-button v-if="editable&&can('POST /api/v1/alarm-governance/rounds/:id/causes')" size="small" @click="open('causes')">记录候选原因</ui-button><ui-button v-if="editable&&can('POST /api/v1/alarm-governance/rounds/:id/measures')" size="small" @click="open('measures')">安排改善 / 进一步检查</ui-button></div><article v-for="row in list('causes')" :key="row.id" class="gov-card"><strong>{{row.cause}}</strong><ui-tag>{{label(row.status)}}</ui-tag><p>{{row.confirmationBasis}}</p><p class="gov-meta">适用事件 {{row.observationIds?.length||0}} 条 · 核实依据 {{row.verificationIds?.length||0}} 份 · 冲突证据 {{row.conflictEvidenceIds?.length||0}} 条</p><div class="gov-actions"><ui-button v-for="action in ['confirm','dispute','reject']" v-if="editable" :key="action" v-show="can(`POST /api/v1/alarm-governance/causes/:id/${action}`)" text size="small" @click="open(`causes:${action}`,row)">{{{confirm:'人工确认原因',dispute:'标记争议',reject:'排除原因'}[action]}}</ui-button></div></article><h3>措施实施与专业验收</h3><article v-for="row in list('measures')" :key="row.id" class="gov-card"><div class="gov-toolbar"><strong>{{row.content}}</strong><ui-tag :type="row.dueAt<Date.now()&&!['VERIFIED','CANCELLED'].includes(row.status)?'warning':'info'">{{label(row.status)}}</ui-tag></div><p class="gov-meta">{{row.ownerUserId}} · 截止 {{time(row.dueAt)}} · {{row.required?'必要措施':'补充措施'}} · {{row.requiresAcceptance?'需要独立验收':'按计划核实实施'}}</p><p>依据：{{row.basis||'待补充'}}</p><p v-if="row.implementation">实施：{{row.implementation}} · {{time(row.implementedAt)}}</p><p v-if="row.acceptance">验收：{{row.acceptance}} · {{time(row.acceptedAt)}}</p><p v-if="row.cancellationReason">取消：{{row.cancellationReason}}；后续 {{row.followup}}</p><div class="gov-actions"><ui-button v-for="action in measureActions(row)" v-if="editable" :key="action" v-show="can(`POST /api/v1/alarm-governance/measures/:id/${action}`)" text size="small" @click="open(`measures:${action}`,row)">{{{start:'开始实施',implement:'记录实施',verify:'独立验收',cancel:'取消并安排后续'}[action]}}</ui-button></div></article></div>
<div v-if="tab==='observation'" class="gov-stack"><div class="gov-actions"><ui-button v-if="editable&&can('POST /api/v1/alarm-governance/rounds/:id/observation-plans')" size="small" @click="open('observation-plans')">制定固定观察计划</ui-button><ui-button v-if="editable&&can('POST /api/v1/alarm-governance/rounds/:id/observation-reviews')" size="small" @click="open('observation-reviews')">基于固定快照评价</ui-button></div><article v-for="row in list('observation-plans')" :key="row.id" class="gov-card"><strong>观察计划 · {{label(row.status)}}</strong><p class="gov-meta">改进前 {{time(row.beforeStart)}} ～ {{time(row.beforeEnd)}}<br/>改进后 {{time(row.afterStart)}} ～ {{time(row.afterEnd)}}</p><p>最低有效监测 {{row.minimumMonitoringHours}} 小时 · 最低实际活动 {{row.minimumActivities}} 次 · {{row.activityUnit}} · {{label(row.coverageRequirement)}}</p><p class="gov-meta">准入 {{row.admissionConditions?.join('；')}} · 排除 {{row.exclusions?.join('；')}} · 复核人 {{row.reviewerUserId}}</p><ui-button v-if="editable&&row.status==='DRAFT'&&can('POST /api/v1/alarm-governance/observation-plans/:id/confirm')" text size="small" @click="open('observation-plans:confirm',row)">确认观察口径</ui-button></article><article v-for="row in list('observation-reviews')" :key="row.id" class="gov-card"><strong>{{label(row.conclusion)}}</strong><ui-tag :type="tone(row.conclusion)">{{label(row.status)}}</ui-tag><p v-for="item in row.limitations" :key="item">{{label(item)}}</p><p>后续 {{row.followup}} · {{row.followupOwnerUserId}}</p><p class="gov-meta">固定快照 {{row.analysisSnapshotId}} · 资料版本 {{row.dataRevision}} · 事实 {{row.factsHash}}</p><ui-button v-if="editable&&row.status==='DRAFT'&&can('POST /api/v1/alarm-governance/observation-reviews/:id/confirm')" text size="small" @click="open('observation-reviews:confirm',row)">正式人工确认</ui-button></article><h3>不可覆盖的正式报告</h3><div v-if="reports.length>1" class="gov-card gov-stack"><h3>固定报告差异复核</h3><div class="gov-grid"><ui-select v-model="comparisonPrevious" placeholder="选择前一正式版本"><ui-option v-for="row in reports" :key="row.id" :value="row.id" :label="`${time(row.confirmedAt)} · ${label(row.conclusion)}`"/></ui-select><ui-select v-model="comparisonCurrent" placeholder="选择后一正式版本"><ui-option v-for="row in reports" :key="row.id" :value="row.id" :label="`${time(row.confirmedAt)} · ${label(row.conclusion)}`"/></ui-select></div><article v-for="(change,index) in reportChanges" :key="index"><strong>{{change.name}}</strong><p class="gov-meta">原版本 {{change.before}}<br/>新版本 {{change.after}}</p></article><p class="gov-meta">差异只比较两份已固定报告；新证据不能覆盖历史人员结论。</p></div><article v-for="row in reports" :key="row.id" class="gov-card"><strong>{{label(row.conclusion)}} · {{time(row.confirmedAt)}}</strong><p class="gov-meta">轮次 {{row.roundId}} · 确认人 {{row.confirmedBy}} · 固定资料 {{row.dataRevision}}</p><p v-for="item in row.limitations" :key="item">{{label(item)}}</p><p>后续 {{row.followup}} · {{row.followupOwnerUserId}}</p><ui-button v-if="can('GET /api/v1/alarm-governance/reports/:id/analysis')" text size="small" @click="showReport(row)">查看本报告冻结指标与分母</ui-button><ui-button v-if="can('GET /api/v1/alarm-governance/reports/:id/export')" text size="small" @click="governanceExport(row.id).catch(cause=>error=cause.message)">下载固定报告</ui-button></article><ui-empty v-if="!reports.length" description="尚未完成正式确认；分析结果不会自动变成报告。"/></div>
<div v-if="tab==='history'" class="gov-stack"><h3>现场附件</h3><div v-if="can('POST /api/v1/alarm-governance/cases/:id/attachments')" class="gov-toolbar"><input type="file" accept="image/png,image/jpeg,image/webp,application/pdf" @change="file=$event.target.files?.[0]||null;attachmentKey=createClientId()"/><ui-button size="small" :loading="saving" :disabled="!file" @click="upload">上传到本事项</ui-button></div><article v-for="row in attachments" :key="row.id" class="gov-card"><strong>{{row.name||row.filename||'现场附件'}}</strong><p class="gov-meta">{{row.mime||row.mimeType}} · {{row.size}} 字节 · {{row.availability||'可用性待核实'}}</p><ui-button text size="small" :disabled="row.availability==='WITHDRAWN'" @click="governanceAttachment(row.id,row.name).catch(cause=>error=cause.message)">授权下载</ui-button><ui-button v-if="row.availability!=='WITHDRAWN'&&can('DELETE /api/v1/alarm-governance/attachments/:id')" text size="small" @click="open('attachments:withdraw',row)">撤回附件并保留理由</ui-button></article><ui-button v-if="can('POST /api/v1/alarm-governance/cases/:id/business-links')" size="small" @click="open('business-links')">关联值班 / 视频证据</ui-button><article v-for="row in businessLinks" :key="row.id" class="gov-card"><strong>{{row.summary}}</strong><p>{{row.relation}}</p><p class="gov-meta">{{row.targetKind==='DUTY_ITEM'?'值班事项':row.targetKind==='VIDEO_EVENT'?'历史视频事件':'值班记录'}} · 固定版本 {{row.targetVersion}} · {{row.syncStatus}} · {{row.correctionReason}}</p><template v-if="row.targetKind==='VIDEO_EVENT'"><p class="gov-meta">同区同时间只说明证据关系；现场成因仍需人工核查。</p><ui-button v-if="can('GET /api/v1/alarm-governance/business-links/:id/media')" text size="small" @click="governanceMedia(row.id,'snapshot').catch(cause=>error=cause.message)">授权下载截图</ui-button><ui-button v-if="can('GET /api/v1/alarm-governance/business-links/:id/media')" text size="small" @click="governanceMedia(row.id,'clip').catch(cause=>error=cause.message)">授权下载录像</ui-button></template><ui-button v-else-if="can('menu:duty')" text size="small" @click="emit('navigate','duty',{deviceId:current.deviceId})">查看来源</ui-button></article><h3>本轮不可变时间线</h3><article v-for="row in list('events')" :key="row.id" class="gov-card"><strong>{{eventLabel(row.action)}}</strong><p>{{row.reason}}</p><p class="gov-meta">{{row.actor}} · 发生 {{time(row.occurredAt)}} · 登记 {{time(row.recordedAt)}} · 资源版本 {{row.resourceVersion}}</p></article><ui-pagination :current-page="eventPage" :page-size="20" :total="eventTotal" @current-change="eventPage=$event"/></div>
<div class="gov-actions"><template v-for="[kind,title] in [['rounds','历史轮次'],['reports','正式报告'],['alarm-links','事件关联'],['verification-links','核实关联'],['causes','原因'],['measures','措施'],['observation-plans','观察计划'],['observation-reviews','观察评价'],['business-links','业务来源'],['attachments','现场附件']]" :key="kind"><ui-button v-if="(kind==='rounds'?rounds.length:kind==='reports'?reports.length:kind==='business-links'?businessLinks.length:kind==='attachments'?attachments.length:list(kind).length)<totals[kind]" size="small" :loading="moreBusy===kind" @click="more(kind)">加载更多{{title}}（{{kind==='rounds'?rounds.length:kind==='reports'?reports.length:kind==='business-links'?businessLinks.length:kind==='attachments'?attachments.length:list(kind).length}} / {{totals[kind]}}）</ui-button></template><ui-button v-if="verificationOffset<totals.verifications" size="small" :loading="moreBusy==='verifications'" @click="more('verifications')">加载更多可关联核实（已查 {{verificationOffset}} / {{totals.verifications}}）</ui-button></div>
<VerificationDialog v-model="verificationDialog" :devices="devices" :configs="configs" :initial="verificationInitial||current" :round-id="editable?roundId:''" @saved="load" @navigate="(...args)=>emit('navigate',...args)"/>
</template></section>
<ui-dialog :model-value="!!selectedReport" title="正式报告的固定分析依据" width="min(1000px,96vw)" @update:model-value="value=>{if(!value)selectedReport=null}"><div class="gov-dialog-body"><ui-skeleton v-if="reportLoading" :rows="4"/><ui-alert v-if="reportError" :title="reportError" type="error" :closable="false"/><template v-if="reportAnalysis"><p class="gov-meta">报告固定快照 {{selectedReport?.analysisSnapshotId}} · 事实 {{selectedReport?.factsHash}}</p><article v-for="plan in reportPlans" :key="plan.id" class="gov-card"><h3>固定观察口径与排除区间</h3><p>{{time(plan.beforeStart)}} ～ {{time(plan.beforeEnd)}} / {{time(plan.afterStart)}} ～ {{time(plan.afterEnd)}}</p><p>{{plan.activityType}} · {{plan.activityUnit}} · {{label(plan.timeBasis)}} · 最低 {{plan.minimumMonitoringHours}} 小时 / {{plan.minimumActivities}} 次</p><p v-for="(interval,index) in plan.monitoringIntervals||[]" :key="index" class="gov-meta">{{label(interval.kind)}} · {{time(interval.start)}} ～ {{time(interval.end)}} · {{interval.basis}}</p><p>{{plan.exclusions?.join('；')}}</p></article><GovernanceResults :run="reportAnalysis.run" :devices="devices" read-only @navigate="(...args)=>emit('navigate',...args)"/><p class="gov-meta">对应固定任务 {{reportAnalysis.run.id}} · {{label(reportAnalysis.run.status)}}</p><ui-button size="small" @click="emit('viewRun',reportAnalysis.run)">查看对应固定任务</ui-button></template></div><template #footer><ui-button @click="selectedReport=null;reportAnalysis=null">关闭固定报告依据</ui-button></template></ui-dialog>
<ui-dialog :model-value="!!dialog" :title="{causes:'候选原因',measures:'改善措施','observation-plans':'固定观察计划','observation-reviews':'人工观察评价','alarm-links':'关联具体事件','verification-links':'关联独立核实',complete:'固定正式报告并完成本轮',reopen:'复核复发并重开新轮'}[dialog]||'记录人工动作'" width="min(780px,94vw)" :close-on-click-modal="false" @update:model-value="value=>{if(!value)dialog=''}"><div class="gov-dialog-body"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-form label-position="top" :disabled="saving"><ui-form-item v-if="['causes','alarm-links','verification-links','reopen'].includes(dialog)" label="明确适用事件" required><ui-select v-model="form.observationIds" multiple filterable><ui-option v-for="row in observations" :key="row.id" :value="row.id" :label="`${time(row.eventAt)} · ${label(row.factKind)} · ${row.id}`"/></ui-select></ui-form-item><template v-if="dialog==='causes'"><ui-form-item label="候选原因" required><ui-input v-model="form.cause"/></ui-form-item><ui-form-item label="已有核实依据"><ui-select v-model="form.verificationIds" multiple filterable><ui-option v-for="row in verificationRows" :key="row.id" :value="row.id" :label="`${label(row.fieldResult)} · ${time(row.verifiedAt)}`"/></ui-select></ui-form-item><ui-form-item label="支持证据（明确事件或附件）" required><ui-select v-model="form.supportEvidenceIds" multiple filterable><ui-option v-for="row in [...observations,...attachments]" :key="row.id" :value="row.id" :label="`${row.name||label(row.factKind)} · ${row.id}`"/></ui-select></ui-form-item><ui-form-item label="冲突证据"><ui-select v-model="form.conflictEvidenceIds" multiple filterable><ui-option v-for="row in [...observations,...attachments]" :key="row.id" :value="row.id" :label="`${row.name||label(row.factKind)} · ${row.id}`"/></ui-select></ui-form-item><ui-form-item label="支持依据 / 同时存在的冲突"><ui-input v-model="form.confirmationBasis" type="textarea" :rows="3"/></ui-form-item></template><template v-if="dialog==='measures'"><ui-form-item label="措施内容" required><ui-input v-model="form.content" type="textarea" :rows="3"/></ui-form-item><div class="gov-grid"><ui-form-item label="负责人" required><ui-input v-model="form.ownerUserId"/></ui-form-item><ui-form-item label="期限" required><ui-date-time v-model="form.dueAt"/></ui-form-item><ui-form-item label="措施条件"><div class="gov-stack"><ui-checkbox v-model="form.required">必要措施</ui-checkbox><ui-checkbox v-model="form.requiresAcceptance">需要独立专业验收</ui-checkbox></div></ui-form-item></div><ui-form-item label="适用依据"><ui-input v-model="form.basis" type="textarea"/></ui-form-item></template><template v-if="dialog==='observation-plans'"><div class="gov-grid"><ui-form-item label="改善前窗口" required><ui-date-range v-model="form.before"/></ui-form-item><ui-form-item label="改善后窗口" required><ui-date-range v-model="form.after"/></ui-form-item><ui-form-item label="活动类型"><ui-select v-model="form.activityType" filterable allow-create><ui-option v-for="option in (configs['scene-presets']||[]).map(recordBody).find(row=>row.id===round?.scenePresetRevisionId)?.activityOptions||[]" :key="option.code" :value="option.code" :label="option.label"/></ui-select></ui-form-item><ui-form-item label="时间依据" required><ui-select v-model="form.timeBasis"><ui-option value="EVENT_AT" label="已核实事件时间"/><ui-option value="RECEIVED_AT" label="平台接收时间分布"/></ui-select></ui-form-item><ui-form-item label="固定活动单位" required><ui-input v-model="form.activityUnit"/></ui-form-item><ui-form-item label="最低有效监测小时" required><ui-input-number v-model="form.minimumMonitoringHours" :min="0"/></ui-form-item><ui-form-item label="最低实际活动数" required><ui-input-number v-model="form.minimumActivities" :min="0" :precision="0"/></ui-form-item><ui-form-item label="复核负责人" required><ui-input v-model="form.reviewerUserId"/></ui-form-item></div><ui-form-item label="改善前现场条件"><ui-input v-model="form.beforeConditions" type="textarea" placeholder="型号、位置、运行时间和实际作业方式"/></ui-form-item><ui-form-item label="改善后现场条件"><ui-input v-model="form.afterConditions" type="textarea" placeholder="如实记录相同与变化的条件"/></ui-form-item><h3>人工核实的可用监测与排除区间</h3><article v-for="(interval,index) in form.monitoringIntervals" :key="index" class="gov-card"><div class="gov-grid"><ui-form-item label="明确区间"><ui-date-range v-model="interval.range"/></ui-form-item><ui-form-item label="监测 / 排除依据"><ui-select v-model="interval.kind"><ui-option v-for="[code,title] in [['VERIFIED_MONITORING','探测功能已核实可用'],['TEST','测试'],['STOPPED','明确停用'],['OFFLINE','明确离线'],['GAP','采集缺口'],['CLOCK_UNKNOWN','时钟不可比较']]" :key="code" :value="code" :label="title"/></ui-select></ui-form-item><ui-form-item label="现场验证依据" required><ui-input v-model="interval.basis"/></ui-form-item></div><ui-button text size="small" @click="form.monitoringIntervals.splice(index,1)">移除区间</ui-button></article><ui-button size="small" @click="form.monitoringIntervals.push({range:null,kind:'',basis:''})">添加监测 / 排除区间</ui-button><ui-form-item label="准入条件（每行一项）"><ui-input v-model="form.admissionText" type="textarea"/></ui-form-item><ui-form-item label="排除条件（每行一项）"><ui-input v-model="form.exclusionsText" type="textarea"/></ui-form-item><p class="gov-meta">观察要求按本现场制定。仅报警登记或来源未知时，不计算完整活动比例。</p></template><template v-if="dialog==='observation-reviews'"><div class="gov-grid"><ui-form-item label="本轮已确认计划" required><ui-select v-model="form.planId"><ui-option v-for="row in list('observation-plans').filter(row=>row.status==='CONFIRMED')" :key="row.id" :value="row.id" :label="`版本 ${row.version} · ${time(row.afterStart)}`"/></ui-select></ui-form-item><ui-form-item label="已完成固定分析" required><ui-select v-model="form.runId"><ui-option v-for="row in (runs||[]).filter(row=>row.snapshotId&&row.parameters?.jobMode!=='HISTORICAL_PROJECTION'&&row.parameters?.caseId===caseId&&row.parameters?.planId===form.planId).sort((a,b)=>b.createdAt-a.createdAt)" :key="row.id" :value="row.id" :label="`${time(row.createdAt)} · ${label(row.status)}`"/></ui-select></ui-form-item><ui-form-item label="固定比较结论（人工复核后确认）" required><ui-select v-model="form.conclusion" disabled><ui-option v-for="code in ['IMPROVED','NOT_IMPROVED','WORSENED','INSUFFICIENT_DATA','NOT_COMPARABLE']" :key="code" :value="code" :label="label(code)"/></ui-select></ui-form-item><ui-form-item label="后续负责人" required><ui-input v-model="form.followupOwnerUserId"/></ui-form-item></div><p v-if="reviewSnapshot" class="gov-meta">结论及系统限制来自本次固定快照；正式确认保留全部限制。现场依据和后续安排由负责人补充。</p><ui-form-item label="具体限制（每行一项）"><ui-input v-model="form.limitationsText" type="textarea"/></ui-form-item><ui-form-item label="后续安排" required><ui-input v-model="form.followup" type="textarea"/></ui-form-item></template><ui-form-item v-if="dialog==='verification-links'" label="独立核实记录" required><ui-select v-model="form.verificationId"><ui-option v-for="row in verificationRows" :key="row.id" :value="row.id" :label="`${label(row.fieldResult)} · ${time(row.verifiedAt)}`"/></ui-select></ui-form-item><ui-form-item v-if="dialog==='complete'" label="已正式确认评价" required><ui-select v-model="form.reviewId"><ui-option v-for="row in list('observation-reviews').filter(row=>row.status==='CONFIRMED')" :key="row.id" :value="row.id" :label="`${label(row.conclusion)} · ${time(row.confirmedAt)}`"/></ui-select></ui-form-item><template v-if="dialog==='confirm-identity'"><ui-form-item label="现场实物版本标识" required><ui-input v-model="form.assetInstanceId" placeholder="明确当前实物；更换实物须建立新关联事项"/></ui-form-item><ui-form-item label="实际核查依据" required><ui-input v-model="form.identityBasis" type="textarea"/></ui-form-item></template><div v-if="dialog==='reopen'" class="gov-grid"><ui-form-item v-for="kind in ['templates','scene-presets','type-profiles']" :key="kind" label="新轮次固定配置"><ui-select v-model="form[{templates:'templateRevisionId','scene-presets':'scenePresetRevisionId','type-profiles':'typeProfileRevisionId'}[kind]]"><ui-option v-for="row in (configs[kind]||[]).map(recordBody).filter(row=>row.status==='PUBLISHED')" :key="row.id" :value="row.id" :label="`${row.name} · 版本 ${row.revisionNumber}`"/></ui-select></ui-form-item></div><ui-form-item v-if="dialog==='assign'||dialog==='reopen'" label="负责人" required><ui-input v-model="form.ownerUserId"/></ui-form-item><ui-form-item v-if="dialog==='measures:implement'" label="实际实施记录" required><ui-input v-model="form.implementation" type="textarea"/></ui-form-item><ui-form-item v-if="dialog==='measures:verify'" label="独立验收依据" required><ui-input v-model="form.acceptance" type="textarea"/></ui-form-item><template v-if="dialog==='measures:cancel'"><ui-form-item label="取消理由" required><ui-input v-model="form.cancellationReason"/></ui-form-item><ui-form-item label="后续安排" required><ui-input v-model="form.followup"/></ui-form-item></template><ui-form-item v-if="dialog.startsWith('causes:')" label="确认 / 争议 / 排除依据" required><ui-input v-model="form.confirmationBasis" type="textarea"/></ui-form-item><template v-if="dialog==='business-links'"><ui-form-item label="目标资源类别"><ui-select v-model="form.targetKind"><ui-option value="DUTY_ITEM" label="值班事项"/><ui-option value="DUTY_RECORD" label="值班记录"/><ui-option v-if="can('GET /api/v1/alarm-governance/video-events')" value="VIDEO_EVENT" label="受控历史视频事件"/></ui-select></ui-form-item><template v-if="form.targetKind==='VIDEO_EVENT'"><ui-form-item label="历史视频有界区间"><ui-date-range v-model="sourceRange"/></ui-form-item><ui-button size="small" :loading="sourceLoading" @click="loadVideoSources()">读取授权历史视频事件</ui-button><p class="gov-meta">只提供本设备当前授权的历史事件。摄像头绑定与时间邻近不自动认定为成因；远程 URL 无法作为本地媒体代理。</p><ui-button v-if="sourceCursor" size="small" :loading="sourceLoading" @click="loadVideoSources(true)">加载下一页视频事件</ui-button></template><ui-form-item label="目标受权资源" required><ui-select v-model="form.targetId" filterable :loading="sourceLoading"><ui-option v-for="row in sourceChoices" :key="row.id" :value="row.id" :label="`${row.title||row.content||row.id} · 版本 ${row.version}`"/></ui-select></ui-form-item><ui-form-item label="目标固定版本"><ui-input-number v-model="form.targetVersion" :min="1" disabled/></ui-form-item><ui-form-item label="关联关系"><ui-input v-model="form.relation"/></ui-form-item></template><ui-form-item v-if="!['causes','measures','observation-plans','observation-reviews'].includes(dialog)" label="实际依据与说明" required><ui-input v-model="form.reason" type="textarea" :rows="3" placeholder="记录本次事实及后续责任；动作不会修改生产告警"/></ui-form-item></ui-form></div><template #footer><ui-button :disabled="saving" @click="dialog=''">取消</ui-button><ui-button type="primary" :loading="saving" @click="mutate">保存人工记录</ui-button></template></ui-dialog>
</template>
